package it.randyflow.domain;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="study_sessions") public class StudySessionEntity { @Id public String id; @Column(name="plan_id") public Long planId; @Column(name="exam_id") public String examId; @Column(name="session_date") public LocalDate sessionDate; public String status; public String topic; @Column(name="slide_from") public Integer slideFrom; @Column(name="slide_to") public Integer slideTo; @Column(name="slides_done") public Integer slidesDone; @Column(name="next_page") public Integer nextPage; @Column(name="duration_min") public int durationMin; @Column(name="previous_duration_min") public Integer previousDurationMin; public String note; public StudySessionEntity() {} }
